import json, sys
sys.path.insert(0, '.')
from cost_model_research import (
    benchmark_draft_overhead, benchmark_components, benchmark_json_overhead,
    build_cost_model, compare_static_vs_adaptive, 
    policy_simplification_analysis, ngram_window_analysis
)

# Run just the cost model sections we care about for saving
overhead_data = benchmark_draft_overhead()
component_data = benchmark_components()
json_data = benchmark_json_overhead()
cost_model = build_cost_model(overhead_data)
static_vs_adaptive = compare_static_vs_adaptive(cost_model)
simplifications = policy_simplification_analysis(component_data, overhead_data, cost_model)
ngram_results = ngram_window_analysis()

# Fix: proper serialization of optimal_n
optimal_n_serial = {}
for prof, pmap in cost_model['optimal_n'].items():
    optimal_n_serial[prof] = {}
    for p, pr_map in pmap.items():
        optimal_n_serial[prof][str(p)] = {}
        for pr, (n, sp) in pr_map.items():
            optimal_n_serial[prof][str(p)][str(pr)] = {'n': n, 'speedup': sp}

all_results = {
    'overhead_benchmark': overhead_data,
    'component_breakdown': {k: v for k, v in component_data.items()},
    'json_serialization': json_data,
    'cost_model': {
        'typical_policy_us': cost_model['typical_policy_us'],
        'policy_ratios': cost_model['policy_ratios'],
        'batch_profiles': cost_model['batch_profiles'],
        'break_even': cost_model['break_even'],
        'optimal_n': optimal_n_serial,
    },
    'static_vs_adaptive': static_vs_adaptive,
    'simplifications': simplifications,
    'ngram_window_analysis': {
        fmt: {str(k): v for k, v in hist.items()} 
        for fmt, hist in ngram_results.items()
    },
}

with open('cost_model_results.json', 'w') as f:
    json.dump(all_results, f, indent=2, default=str)

print('\\\\n=== SAVED ===')
\" 2>&1"

