class HybridPolicy:
    """Policy 4: Hybrid combination of all three approaches.

    Strategy order (each tried in sequence, first valid proposal wins):
      1. Template match (high-confidence structural trigger)
      2. N-gram lookback (repetition detection)
      3. Period-continuation (cheap 1-token draft)

    Also carries acceptance-history state to disable poor-performing
    sub-strategies and adjust aggressiveness.
    """

    def __init__(self):
        # Sub-policies
        self.grammar = PrefixGrammarPolicy()
        self.ngram = NgramReusePolicy(max_n=5, min_n=2, max_draft=12)

        # Acceptance history (shared across strategies)
        self.recent_outcomes = []
        self.max_recent = 30
        self.strategy_stats = defaultdict(lambda: [0, 0])  # [accepted, proposed]
        self.last_strategy = None
        self.draft_factor = 1.0

    def name(self):
        return "hybrid"

    def _recent_quality(self):
        if not self.recent_outcomes:
            return 0.5
        return sum(self.recent_outcomes) / len(self.recent_outcomes)

    def feedback(self, strategy: Optional[str], accepted: int, proposed: int):
        if strategy and proposed > 0:
            self.strategy_stats[strategy][0] += accepted
            self.strategy_stats[strategy][1] += proposed
            good = 1.0 if accepted / proposed > 0.4 else 0.0
            self.recent_outcomes.append(good)
            if len(self.recent_outcomes) > self.max_recent:
                self.recent_outcomes.pop(0)

            quality = self._recent_quality()
            if quality > 0.6:
                self.draft_factor = min(1.5, self.draft_factor + 0.03)
            elif quality < 0.3:
                self.draft_factor = max(0.5, self.draft_factor - 0.03)

    def _strategy_ok(self, strategy: str) -> bool:
        stats = self.strategy_stats.get(strategy, [0, 0])
        if stats[1] >= 5 and stats[0] / stats[1] < 0.1:
            return False
        return True

    def draft(self, state: Dict):
        decoded = state.get("decoded_text", "") or ""
        remaining = state.get("remaining_tokens", 32) or 32
        max_draft = state.get("maximum_draft_tokens", 32) or 32
        budget = min(remaining, max_draft, 32)
        effective_budget = max(1, int(budget * self.draft_factor))
        if budget <= 0:
            self.last_strategy = None
            return {"text": ""}

        # Strategy 1: Template grammar (highest confidence)
        if self._strategy_ok("grammar"):
            result = self.grammar.draft(state)
            draft_words = _draft_to_words(result)
            if draft_words:
                # Trim to effective budget
                trimmed = draft_words[:effective_budget]
                self.last_strategy = "grammar"
                return {"text": " ".join(trimmed)}

        # Strategy 2: N-gram reuse (medium confidence)
        if self._strategy_ok("ngram"):
            result = self.ngram.draft(state)
            draft_words = _draft_to_words(result)
            if draft_words and len(draft_words) >= 2:
                trimmed = draft_words[:effective_budget]
                self.last_strategy = "ngram"
                return {"text": " ".join(trimmed)}

        # Strategy 3: Period continuation (cheap fallback)
        if decoded.strip().endswith(".") and self._strategy_ok("period"):
            self.last_strategy = "period"
            return {"text": "The"}

        self.last_strategy = None
        return {"text": ""}


